def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Start of a field
        if i == len(line):
            # End of line - we've processed all fields
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of the field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == len(line):
                            fields.append(field)
                            i += 1
                            break
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            break
                        else:
                            # Invalid: closing quote not followed by comma or EOL
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                # Skip the comma
                i += 1

    return fields

